steps.script:
$o=@{state='pending'}
try{
 $p=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'"|Where-Object{[string]$_.CommandLine -match 'C:\\TTiTTulares\\Ejecutar[.]js' -and [string]$_.CommandLine -match ' --enviar'})
 if($p.Count){$o.state='runner_active';$o.count=$p.Count}
 else{
  $f=Join-Path $env:TEMP 'Reparar-TT-Editorial-20261111-targeted.ps1'
  Invoke-WebRequest -UseBasicParsing -Uri 'https://raw.githubusercontent.com/fabricelop/europapress-rss/c4216e498eaed67df9cc36d6338bf88742e99f00/windows/Reparar-TT-Editorial-20261111.ps1' -OutFile $f -TimeoutSec 30 -ErrorAction Stop
  & powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $f -NoDispatch | Out-Null
  if($LASTEXITCODE -ne 0){throw 'INSTALL_EXIT_'+$LASTEXITCODE}
  $g=Get-Content 'C:\TTiTTulares\TT-Editorial-Guard.js' -Raw -ErrorAction Stop
  if(-not $g.Contains("editorTag:ed?.tagName")){throw 'GUARD_MARKER_MISSING'}
  $o.state='installed_verified'
 }
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
